public <T> T fetchAndParse(String url, Class<T> type) {
    Objects.requireNonNull(url, 'URL must not be null');
    Objects.requireNonNull(type, 'Type must not be null');

    try {
        java.net.URI uri = java.net.URI.create(url); // throws IllegalArgumentException if invalid
        java.net.http.HttpClient client = java.net.http.HttpClient.newHttpClient();
        java.net.http.HttpRequest request = java.net.http.HttpRequest.newBuilder(uri).GET().build();
        java.net.http.HttpResponse<String> response =
            client.send(request, java.net.http.HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new RemoteApiException(
                'Non-200 response from: ' + url + ', status: ' + response.statusCode());
        }
        return objectMapper.readValue(response.body(), type); // throws JsonProcessingException
    } catch (IllegalArgumentException e) {
        throw e; // Programming error — let it propagate as-is
    } catch (java.net.http.HttpTimeoutException e) {
        throw new RemoteApiException('Request to ' + url + ' timed out', e);
    } catch (IOException | InterruptedException e) {
        if (e instanceof InterruptedException) Thread.currentThread().interrupt();
        throw new RemoteApiException('Failed to fetch data from: ' + url, e);
    }
}
